import "server-only";

import { authors } from "@/lib/api";
import { must } from "@/lib/backend";
import type { Author, Book } from "@/lib/types";

export type AuthorCardProps = {
    author: Pick<Author, "id" | "name" | "born">;
};

export async function readAuthorCard(author: Author): Promise<AuthorCardProps> {
    return {
        author: {
            id: author.id,
            name: author.name,
            born: author.born,
        },
    };
}

export type AuthorViewProps = {
    author: Pick<Author, "id" | "name" | "born"> & {
        books: Pick<Book, "id" | "title">[];
    };
};

export async function readAuthorView(author: Author): Promise<AuthorViewProps> {
    const [books] = await Promise.all([
        must(authors.books(author.id)),
    ]);
    return {
        author: {
            id: author.id,
            name: author.name,
            born: author.born,
            books: books.map((item) => ({ id: item.id, title: item.title })),
        },
    };
}

export type BookCardProps = {
    book: Pick<Book, "id" | "title" | "genre" | "published" | "in_print"> & {
        author: Pick<Author, "id" | "name">;
    };
};

export async function readBookCard(book: Book): Promise<BookCardProps> {
    const [author] = await Promise.all([
        must(authors.get(book.author_id)),
    ]);
    return {
        book: {
            id: book.id,
            title: book.title,
            genre: book.genre,
            published: book.published,
            in_print: book.in_print,
            author: { id: author.id, name: author.name },
        },
    };
}
